<template>
  <!-- Port of XMCL MarketBase/MarketListHeader/MarketFilterPanel language. -->
  <section class="xmcl-market">
    <div class="xmcl-market-tabs"><q-tabs v-model="view" align="left" outside-arrows mobile-arrows><q-tab name="local" label="已安装" icon="folder"/><q-tab name="online" label="下载资源" icon="cloud_download"/></q-tabs><q-space/><q-btn flat round icon="refresh" :disable="busy" @click="loadLocal"/></div>
    <div v-if="view==='local'" class="xmcl-market-local"><div class="xmcl-market-toolbar"><strong>{{ label }} <small>{{ local.length }}</small></strong><q-input dark borderless dense v-model="filter" placeholder="筛选已安装资源"><template #prepend><q-icon name="search"/></template></q-input><q-btn flat icon="update" label="检查更新" :disable="busy" @click="checkUpdates"/></div><div class="xmcl-resource-list"><article v-for="resource in filtered" :key="resource.fileName" class="xmcl-resource-row" @click="inspect(resource)"><q-avatar rounded size="42px" class="resource-icon"><img v-if="resource.iconUrl || resource.icon" :src="resource.iconUrl || resource.icon" :alt="resource.name || resource.fileName"/><q-icon v-else name="extension" size="25px" color="primary"/></q-avatar><div class="xmcl-resource-main"><strong>{{ resource.name||resource.fileName }}</strong><small>{{ resource.fileName }} · {{ resource.version||'本地文件' }}</small></div><q-badge :color="resource.enabled===false?'grey':'positive'">{{ resource.enabled===false?'已禁用':'已启用' }}</q-badge><q-btn flat round dense :icon="resource.enabled===false?'visibility':'visibility_off'" :disable="busy" @click.stop="toggle(resource)"/><q-btn flat round dense icon="delete" color="negative" :disable="busy" @click.stop="remove(resource)"/></article><div v-if="!filtered.length" class="xmcl-market-empty">当前目录没有{{ label }}。</div></div><q-dialog v-model="detailsShown"><q-card class="xmcl-detail"><q-card-section><div class="resource-detail-heading"><q-avatar rounded size="64px" class="resource-icon"><img v-if="details?.iconUrl || details?.icon" :src="details.iconUrl || details.icon"/><q-icon v-else name="extension" size="34px" color="primary"/></q-avatar><div><div class="text-h6">{{ details?.name||details?.metadata?.name||selected?.name||selected?.fileName }}</div><div class="text-caption text-grey-5">{{ details?.fileName||selected?.fileName }}</div></div></div><div class="resource-detail-grid"><div><small>版本</small><span>{{ details?.metadata?.version||details?.version||'未知' }}</span></div><div><small>Minecraft</small><span>{{ details?.metadata?.minecraftVersions?.join(', ')||'未知' }}</span></div><div><small>来源</small><span>{{ details?.metadata?.url||'本地资源' }}</span></div><div><small>状态</small><span>{{ details?.status||'已安装' }}</span></div></div><q-separator class="q-my-md"/><details><summary>查看完整元数据</summary><pre>{{ JSON.stringify(details||selected,null,2) }}</pre></details></q-card-section></q-card></q-dialog></div><div v-else><CatalogBrowser :instance="instance" :kind="kind" :minecraft-version="minecraftVersion" :busy="busy" :execute="execute" @installed="loadLocal"/></div><q-banner v-if="error" class="bg-red-9 q-mt-md">{{ error }}</q-banner>
  </section>
</template>
<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';
import CatalogBrowser from '../components/CatalogBrowser.vue';
const props=defineProps<{instance:string;kind:string;minecraftVersion?:string;busy:boolean;execute:(op:string,p?:Record<string,unknown>)=>Promise<any>}>();
const view=ref('local'),local=ref<any[]>([]),filter=ref(''),error=ref(''),selected=ref<any>(null),details=ref<any>(null),detailsShown=ref(false);const label=computed(()=>({mods:'模组',resourcepacks:'资源包',shaderpacks:'光影包',datapacks:'数据包'} as any)[props.kind]||props.kind);const filtered=computed(()=>local.value.filter(x=>`${x.name||''} ${x.fileName||''}`.toLowerCase().includes(filter.value.toLowerCase())));
async function loadLocal(){try{const r=await props.execute('resource.list',{instance:props.instance,kind:props.kind});local.value=Array.isArray(r)?r:[];}catch(e){error.value=String(e);}}
async function toggle(r:any){try{await props.execute(r.enabled===false?'resource.enable':'resource.disable',{instance:props.instance,kind:props.kind,resource:r.fileName});await loadLocal();}catch(e){error.value=String(e);}}
async function remove(r:any){try{await props.execute('resource.remove',{instance:props.instance,kind:props.kind,resource:r.fileName,confirm:true});await loadLocal();}catch(e){error.value=String(e);}}
async function inspect(r:any){selected.value=r;try{details.value=await props.execute('resource.inspect',{instance:props.instance,kind:props.kind,resource:r.fileName});}catch{details.value=r;}detailsShown.value=true;}
async function checkUpdates(){try{const r=await props.execute('resource.updates.check',{instance:props.instance,kind:props.kind});error.value=r.items?.length?`发现 ${r.items.length} 项更新，请在更新计划中应用。`:'没有可用更新';}catch(e){error.value=String(e);}}
watch(()=>[props.instance,props.kind],loadLocal);onMounted(loadLocal);
</script>
<style scoped>.xmcl-market{margin-top:22px}.xmcl-market-tabs{display:flex;align-items:center;border-bottom:1px solid rgba(255,255,255,.1)}.xmcl-market-toolbar{display:flex;align-items:center;gap:14px;padding:14px 6px}.xmcl-market-toolbar strong{font-size:16px;white-space:nowrap}.xmcl-market-toolbar strong small{font-size:12px;color:rgba(255,255,255,.5)}.xmcl-market-toolbar .q-input{flex:1}.xmcl-resource-list{display:flex;flex-direction:column;gap:6px}.xmcl-resource-row{display:flex;align-items:center;gap:12px;padding:11px 12px;border-radius:10px;background:rgba(255,255,255,.045);border:1px solid rgba(255,255,255,.07);cursor:pointer;transition:background .15s,border-color .15s}.xmcl-resource-row:hover{background:rgba(255,255,255,.09);border-color:rgba(129,140,248,.45)}.resource-icon{background:rgba(255,255,255,.07);flex:none}.xmcl-resource-main{flex:1;min-width:0;display:flex;flex-direction:column}.xmcl-resource-main strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.xmcl-resource-main small{color:rgba(255,255,255,.5);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.xmcl-market-empty{text-align:center;padding:30px;color:rgba(255,255,255,.5)}.xmcl-detail{max-width:720px;width:90vw;background:#222228;color:#fff}.resource-detail-heading{display:flex;align-items:center;gap:14px}.resource-detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px}.resource-detail-grid div{padding:10px;border-radius:8px;background:rgba(255,255,255,.05)}.resource-detail-grid small{display:block;color:rgba(255,255,255,.5);margin-bottom:4px}.resource-detail-grid span{display:block;overflow-wrap:anywhere}.xmcl-detail details{margin-top:10px}.xmcl-detail pre{max-height:40vh;overflow:auto;white-space:pre-wrap}@media(max-width:600px){.resource-detail-grid{grid-template-columns:1fr}}
</style>
